INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (600, 1, 'CPU 의 가상화 방식', '`/tmp/lscpu.log` 는 호스트의 `lscpu` 출력입니다. `Virtualization:` 줄은 CPU 가 지원하는 하드웨어 가상화 방식(Intel 은 VT-x, AMD 는 AMD-V)을 보여 줍니다. 이 호스트의 **가상화 방식 값**을 `/tmp/virt.txt` 에 저장하세요. (값만)', '`Virtualization:` 로 시작하는 줄의 콜론 뒤입니다.', 'cat /tmp/lscpu.log
grep ''^Virtualization:'' /tmp/lscpu.log | awk ''{print $2}'' > /tmp/virt.txt
cat /tmp/virt.txt

# 이 줄이 없으면 CPU 가 지원하지 않거나 BIOS 에서 꺼져 있다. VM 안(중첩 가상화)에서는 다른 값이 보이기도 한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nArchitecture:        x86_64\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nVirtualization:      VT-x\\nEOF\\ncat > /tmp/validate.log <<''EOF''\\n  QEMU: Checking for hardware virtualization                                 : PASS\\n  QEMU: Checking if device /dev/kvm exists                                   : FAIL (Check that the ''kvm-intel'' or ''kvm-amd'' modules are loaded & the BIOS has enabled virtualization)\\n  QEMU: Checking if device /dev/kvm is accessible                            : FAIL (Check /dev/kvm permissions)\\n  QEMU: Checking for cgroup ''memory'' controller support                      : PASS\\nEOF\\ncat > /tmp/dominfo.log <<''EOF''\\nId:             7\\nName:           web01\\nState:          running\\nCPU(s):         2\\nMax memory:     2097152 KiB\\nUsed memory:    1048576 KiB\\nPersistent:     yes\\nAutostart:      disable\\nEOF\\ncat > /tmp/domblklist.log <<''EOF''\\n Target   Source\\n---------------------------------------------\\n vda      /var/lib/libvirt/images/web01.qcow2\\n sda      -\\nEOF\\ncat > /tmp/domifaddr.log <<''EOF''\\n Name       MAC address          Protocol     Address\\n-------------------------------------------------------------------------------\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/virt.txt)\\" = VT-x ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "VT-x 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/virt.txt)\\" = VT-x ]"]}]', '[{"title": "virt-host-validate 매뉴얼", "url": "https://libvirt.org/manpages/virt-host-validate.html"}, {"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}]'),
  (600, 2, '논리 CPU 수 계산', '같은 `lscpu` 출력에서 **소켓 수 × 소켓당 코어 수 × 코어당 스레드 수** 로 계산한 **논리 CPU 수**를 `/tmp/logical.txt` 에 저장하세요. (숫자만, `CPU(s):` 줄과 같아야 합니다)', '세 값을 각각 뽑아 곱하세요. 쉘 산술을 쓸 수 있습니다.', 'S=$(grep ''^Socket'' /tmp/lscpu.log | awk ''{print $2}'')
C=$(grep ''^Core'' /tmp/lscpu.log | awk ''{print $4}'')
T=$(grep ''^Thread'' /tmp/lscpu.log | awk ''{print $4}'')
echo $((S * C * T)) > /tmp/logical.txt
cat /tmp/logical.txt

# 2 × 8 × 2 = 32. vCPU 를 물리 몇 배까지 줄지(오버커밋) 계산할 때 이 값이 기준이 된다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nArchitecture:        x86_64\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nVirtualization:      VT-x\\nEOF\\ncat > /tmp/validate.log <<''EOF''\\n  QEMU: Checking for hardware virtualization                                 : PASS\\n  QEMU: Checking if device /dev/kvm exists                                   : FAIL (Check that the ''kvm-intel'' or ''kvm-amd'' modules are loaded & the BIOS has enabled virtualization)\\n  QEMU: Checking if device /dev/kvm is accessible                            : FAIL (Check /dev/kvm permissions)\\n  QEMU: Checking for cgroup ''memory'' controller support                      : PASS\\nEOF\\ncat > /tmp/dominfo.log <<''EOF''\\nId:             7\\nName:           web01\\nState:          running\\nCPU(s):         2\\nMax memory:     2097152 KiB\\nUsed memory:    1048576 KiB\\nPersistent:     yes\\nAutostart:      disable\\nEOF\\ncat > /tmp/domblklist.log <<''EOF''\\n Target   Source\\n---------------------------------------------\\n vda      /var/lib/libvirt/images/web01.qcow2\\n sda      -\\nEOF\\ncat > /tmp/domifaddr.log <<''EOF''\\n Name       MAC address          Protocol     Address\\n-------------------------------------------------------------------------------\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/logical.txt)\\" = 32 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "32 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/logical.txt)\\" = 32 ]"]}]', '[{"title": "virt-host-validate 매뉴얼", "url": "https://libvirt.org/manpages/virt-host-validate.html"}, {"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}]'),
  (600, 3, '호스트 점검의 실패 항목', '`/tmp/validate.log` 는 `virt-host-validate` 의 출력입니다. 각 줄 끝이 `PASS` 또는 `FAIL` 입니다. **실패(`FAIL`)한 항목의 개수**를 숫자만 `/tmp/fails.txt` 에 저장하세요.', '`FAIL` 이 들어간 줄의 수를 세세요.', 'cat /tmp/validate.log
grep -c ''FAIL'' /tmp/validate.log > /tmp/fails.txt
cat /tmp/fails.txt

# CPU 는 지원하는데 /dev/kvm 이 없다. 메시지처럼 kvm 모듈이 올라오지 않았거나 BIOS 에서 가상화가 꺼져 있는 경우가 많다. 모듈은 modprobe kvm_intel 로 올린다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nArchitecture:        x86_64\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nVirtualization:      VT-x\\nEOF\\ncat > /tmp/validate.log <<''EOF''\\n  QEMU: Checking for hardware virtualization                                 : PASS\\n  QEMU: Checking if device /dev/kvm exists                                   : FAIL (Check that the ''kvm-intel'' or ''kvm-amd'' modules are loaded & the BIOS has enabled virtualization)\\n  QEMU: Checking if device /dev/kvm is accessible                            : FAIL (Check /dev/kvm permissions)\\n  QEMU: Checking for cgroup ''memory'' controller support                      : PASS\\nEOF\\ncat > /tmp/dominfo.log <<''EOF''\\nId:             7\\nName:           web01\\nState:          running\\nCPU(s):         2\\nMax memory:     2097152 KiB\\nUsed memory:    1048576 KiB\\nPersistent:     yes\\nAutostart:      disable\\nEOF\\ncat > /tmp/domblklist.log <<''EOF''\\n Target   Source\\n---------------------------------------------\\n vda      /var/lib/libvirt/images/web01.qcow2\\n sda      -\\nEOF\\ncat > /tmp/domifaddr.log <<''EOF''\\n Name       MAC address          Protocol     Address\\n-------------------------------------------------------------------------------\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/fails.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "2 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/fails.txt)\\" = 2 ]"]}]', '[{"title": "virt-host-validate 매뉴얼", "url": "https://libvirt.org/manpages/virt-host-validate.html"}, {"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}]'),
  (600, 4, '최대 메모리를 MiB 로', '`/tmp/dominfo.log` 는 `virsh dominfo web01` 의 출력입니다. `Max memory` 는 KiB 단위입니다. 이 VM 의 **최대 메모리를 MiB 로 환산**한 값(정수)을 `/tmp/max_mib.txt` 에, **현재 상태(`State`)** 를 `/tmp/state.txt` 에 저장하세요.', 'KiB 를 1024 로 나누면 MiB 입니다. `State:` 줄은 콜론 뒤 한 단어입니다.', 'cat /tmp/dominfo.log
K=$(grep ''Max memory'' /tmp/dominfo.log | awk ''{print $3}'')
echo $((K / 1024)) > /tmp/max_mib.txt
grep ''^State:'' /tmp/dominfo.log | awk ''{print $2}'' > /tmp/state.txt
cat /tmp/max_mib.txt /tmp/state.txt

# 최대 2048MiB 인데 사용 중(Used memory)은 1024MiB 다. 풍선(balloon) 드라이버로 게스트에 실제 준 메모리를 줄여 둔 상태일 수 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nArchitecture:        x86_64\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nVirtualization:      VT-x\\nEOF\\ncat > /tmp/validate.log <<''EOF''\\n  QEMU: Checking for hardware virtualization                                 : PASS\\n  QEMU: Checking if device /dev/kvm exists                                   : FAIL (Check that the ''kvm-intel'' or ''kvm-amd'' modules are loaded & the BIOS has enabled virtualization)\\n  QEMU: Checking if device /dev/kvm is accessible                            : FAIL (Check /dev/kvm permissions)\\n  QEMU: Checking for cgroup ''memory'' controller support                      : PASS\\nEOF\\ncat > /tmp/dominfo.log <<''EOF''\\nId:             7\\nName:           web01\\nState:          running\\nCPU(s):         2\\nMax memory:     2097152 KiB\\nUsed memory:    1048576 KiB\\nPersistent:     yes\\nAutostart:      disable\\nEOF\\ncat > /tmp/domblklist.log <<''EOF''\\n Target   Source\\n---------------------------------------------\\n vda      /var/lib/libvirt/images/web01.qcow2\\n sda      -\\nEOF\\ncat > /tmp/domifaddr.log <<''EOF''\\n Name       MAC address          Protocol     Address\\n-------------------------------------------------------------------------------\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/max_mib.txt)\\" = 2048 ] ) && ( [ \\"$(cat /tmp/state.txt)\\" = running ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "2048 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/max_mib.txt)\\" = 2048 ]"]}, {"label": "running 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/state.txt)\\" = running ]"]}]', '[{"title": "virt-host-validate 매뉴얼", "url": "https://libvirt.org/manpages/virt-host-validate.html"}, {"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}]'),
  (600, 5, '디스크 이미지 경로', '`/tmp/domblklist.log` 는 `virsh domblklist web01` 의 출력입니다. 이 VM 에 **실제 이미지 파일이 연결된 디스크의 경로**(`Source` 열, `-` 는 비어 있음)를 `/tmp/image.txt` 에 저장하세요. (경로만)', '`Source` 열이 `-` 가 아닌 줄의 마지막 칸입니다.', 'cat /tmp/domblklist.log
awk ''NR>2 && $2 != "-" {print $2}'' /tmp/domblklist.log > /tmp/image.txt
cat /tmp/image.txt

# sda 는 비어 있는 장치(CD-ROM 등)다. 이 경로의 파일이 지워지거나 권한이 바뀌면 VM 시작이 실패한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nArchitecture:        x86_64\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nVirtualization:      VT-x\\nEOF\\ncat > /tmp/validate.log <<''EOF''\\n  QEMU: Checking for hardware virtualization                                 : PASS\\n  QEMU: Checking if device /dev/kvm exists                                   : FAIL (Check that the ''kvm-intel'' or ''kvm-amd'' modules are loaded & the BIOS has enabled virtualization)\\n  QEMU: Checking if device /dev/kvm is accessible                            : FAIL (Check /dev/kvm permissions)\\n  QEMU: Checking for cgroup ''memory'' controller support                      : PASS\\nEOF\\ncat > /tmp/dominfo.log <<''EOF''\\nId:             7\\nName:           web01\\nState:          running\\nCPU(s):         2\\nMax memory:     2097152 KiB\\nUsed memory:    1048576 KiB\\nPersistent:     yes\\nAutostart:      disable\\nEOF\\ncat > /tmp/domblklist.log <<''EOF''\\n Target   Source\\n---------------------------------------------\\n vda      /var/lib/libvirt/images/web01.qcow2\\n sda      -\\nEOF\\ncat > /tmp/domifaddr.log <<''EOF''\\n Name       MAC address          Protocol     Address\\n-------------------------------------------------------------------------------\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/image.txt)\\" = /var/lib/libvirt/images/web01.qcow2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "web01.qcow2 경로다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/image.txt)\\" = /var/lib/libvirt/images/web01.qcow2 ]"]}]', '[{"title": "virt-host-validate 매뉴얼", "url": "https://libvirt.org/manpages/virt-host-validate.html"}, {"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}]'),
  (600, 6, 'IP 조회 비어 있음과 에이전트', '`/tmp/domifaddr.log` 는 VM 이 켜진 뒤 `virsh domifaddr web01` 의 출력으로 주소 항목이 **하나도 없습니다**. 게스트에 에이전트(qemu-guest-agent)가 있으면 **에이전트를 통해** 주소를 물어볼 수 있습니다. 그 `virsh` 명령 한 줄을 `/tmp/agent_cmd.txt` 에 적으세요. (샌드박스에는 libvirt 가 없어 실행하지 않습니다)', '`domifaddr` 에 주소를 얻는 출처를 정하는 옵션이 있습니다.', 'cat /tmp/domifaddr.log
echo ''virsh domifaddr web01 --source agent'' > /tmp/agent_cmd.txt
cat /tmp/agent_cmd.txt

# 기본은 DHCP 임대 목록(lease)에서 찾는다. 고정 IP 나 외부 브리지에 붙으면 목록에 없어 비어 보이므로 에이전트나 ARP 로 조회한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/lscpu.log <<''EOF''\\nArchitecture:        x86_64\\nCPU(s):              32\\nThread(s) per core:  2\\nCore(s) per socket:  8\\nSocket(s):           2\\nVirtualization:      VT-x\\nEOF\\ncat > /tmp/validate.log <<''EOF''\\n  QEMU: Checking for hardware virtualization                                 : PASS\\n  QEMU: Checking if device /dev/kvm exists                                   : FAIL (Check that the ''kvm-intel'' or ''kvm-amd'' modules are loaded & the BIOS has enabled virtualization)\\n  QEMU: Checking if device /dev/kvm is accessible                            : FAIL (Check /dev/kvm permissions)\\n  QEMU: Checking for cgroup ''memory'' controller support                      : PASS\\nEOF\\ncat > /tmp/dominfo.log <<''EOF''\\nId:             7\\nName:           web01\\nState:          running\\nCPU(s):         2\\nMax memory:     2097152 KiB\\nUsed memory:    1048576 KiB\\nPersistent:     yes\\nAutostart:      disable\\nEOF\\ncat > /tmp/domblklist.log <<''EOF''\\n Target   Source\\n---------------------------------------------\\n vda      /var/lib/libvirt/images/web01.qcow2\\n sda      -\\nEOF\\ncat > /tmp/domifaddr.log <<''EOF''\\n Name       MAC address          Protocol     Address\\n-------------------------------------------------------------------------------\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"^[[:space:]]*(sudo )?virsh( (-c|--connect)[ =]?[^ ]+)? domifaddr( .*)? web01( .*)?$\\" /tmp/agent_cmd.txt && grep -Eq -- \\"--source[= ]agent\\" /tmp/agent_cmd.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "domifaddr 에이전트 명령이다", "cmd": ["sh", "-c", "grep -Eq \\"^[[:space:]]*(sudo )?virsh( (-c|--connect)[ =]?[^ ]+)? domifaddr( .*)? web01( .*)?$\\" /tmp/agent_cmd.txt && grep -Eq -- \\"--source[= ]agent\\" /tmp/agent_cmd.txt"]}]', '[{"title": "virt-host-validate 매뉴얼", "url": "https://libvirt.org/manpages/virt-host-validate.html"}, {"title": "virsh 매뉴얼", "url": "https://libvirt.org/manpages/virsh.html"}]'),
  (600, 7, 'shutdown, reboot, destroy', 'VM 을 정리하는 virsh 명령의 차이로 알맞은 것은?', '정상 종료 요청과 전원을 뽑는 것을 구분하세요.', NULL, NULL, '[]', 'choice', '["shutdown 은 VM 을 삭제하고 destroy 는 정상 종료한다", "reboot 은 VM 을 재시작하면서 정의까지 삭제한다", "shutdown 은 정상 종료를 요청하고 destroy 는 전원을 즉시 끊는다", "destroy 는 VM 정의와 디스크를 모두 삭제한다"]', 2, '`shutdown` 은 게스트에 종료 신호(ACPI·에이전트)를 보내 정상 종료하고, `destroy` 는 전원을 뽑는 것과 같아 강제로 끕니다(정의와 디스크는 남음). 정의를 지우는 것은 `undefine` 입니다.', NULL, NULL, NULL, NULL),
  (600, 8, 'Used memory 가 Max 보다 작은 이유', 'dominfo 에서 `Max memory` 는 2097152 KiB 인데 `Used memory` 는 1048576 KiB 입니다. 가장 알맞은 해석은?', '게스트에 실제로 할당된 메모리와 허용 상한은 다를 수 있습니다.', NULL, NULL, '[]', 'choice', '["메모리 하나가 고장나서 절반이 사라진 것이다", "풍선(balloon)으로 게스트 메모리를 줄여 둔 상태일 수 있다", "호스트가 VM 의 메모리를 두 배로 늘려 준 것이다", "VM 이 곧 삭제될 예정이라 메모리를 줄인 것이다"]', 1, 'Max memory 는 허용 상한, Used memory(currentMemory)는 지금 게스트에 할당된 양입니다. balloon 으로 호스트가 회수해 가면 줄어 있고 setmem 으로 상한까지 올릴 수 있습니다.', NULL, NULL, NULL, NULL),
  (600, 9, 'VM 요약 보기', 'VM 의 이름·상태·CPU 수·메모리 요약을 보는 virsh 명령을 채우세요.', '정보(information) 요약이라는 뜻의 하위 명령입니다.', NULL, NULL, '[]', 'fill', '["dominfo", "domstats", "list", "version"]', NULL, '`dominfo` 는 도메인 한 개의 기본 정보를 요약합니다. `domstats` 는 통계(CPU·블록·네트워크), `list` 는 VM 목록, `version` 은 libvirt·하이퍼바이저 버전입니다.', '[0]', 'virsh {0} web01', NULL, NULL),
  (600, 10, '호스트에서 KVM 사용 가능 여부 확인', 'KVM 을 쓸 수 있는지 확인하려 합니다. 하드웨어에서 소프트웨어 쪽으로 한 칸씩 올라가며 확인하는 순서로 놓으세요.', '아래 계층이 안 되면 위 계층은 확인할 필요가 없습니다.', NULL, NULL, '[]', 'order', '["`virt-host-validate` 로 종합 점검한다", "`lsmod | grep kvm` 으로 KVM 모듈이 올라와 있는지 본다", "`/dev/kvm` 장치 파일이 있는지 본다", "CPU 의 가상화 지원(vmx·svm)을 본다"]', NULL, 'CPU 지원 → 커널 모듈 → 장치 파일 → 종합 점검 순서로 확인합니다. 앞 단계에서 막히면(BIOS 에서 꺼짐, 모듈 없음) 뒤 단계도 실패합니다.', '[3, 1, 2, 0]', NULL, NULL, NULL);
